INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770341784181, 'Speakers', 'DP2-653', 'Pro 3-Way Component Speaker Set', '장착 공임 별도/20만원 부터', 800000, 'assets/images/spk-dp2653.jpg', '[{"id":1770341301379.8967,"type":"text","value":"60Hz~40kHz\nTweeter : 1\"\nMid : 3.5\"\nWoofer : 6.5\"\nPeak : 240W\nSensitivity : 90dB"},{"id":1770341388459.2117,"type":"image","value":"assets/images/spk-dp2653-01.jpg"},{"id":1770341431695.9292,"type":"text","value":"DP2 스피커는 60Hz부터 40,000Hz의 주파스를 재생할 수 있어 음악을 원래 음원에 더 가깝게 만듭니다."},{"id":1770341510267.773,"type":"image","value":"assets/images/spk-dp2653-02.jpg"},{"id":1770341520877.3308,"type":"text","value":"예술 작품에 가깝습니다.\n\n외관 디자인은 고품질 알루미늄 합금 소재를 사용하여\n재생 공명을 효과적으로 제거하고 정확한 사운드 성능을 보장합니다."},{"id":1770341568503.3345,"type":"image","value":"assets/images/spk-dp2653-03.jpg"},{"id":1770341596091.7383,"type":"text","value":"세계 최초 \"Hybrid fiber\"를 사용하였습니다.\n\n고강성 탄소섬유는 베이스의 힘을 반영하고, 고강성 방탄섬유는 미드톤의 부드러운 목소리를 선명하게 반영하며, 통일된 진동판 소재를 사용한 베이스 유닛인 미드톤은 넓은 범위의 음원을 자연스럽게 합니다.\n\nHAMR Surround 채용\n\n알파인의 고유 기술인 H.A.M.R(High Amplitude Multi-Roll) 서라운드는 고급 사운드 시스템을 채택하여 높은 출력과 뛰어난 음질을 구현합니다."},{"id":1770341801893.0098,"type":"image","value":"assets/images/spk-dp2653-04.jpg"},{"id":1770341834165.266,"type":"text","value":"알루미늄 마그네슘 합금 트위터는 천상의 악기 소리를 재현합니다.\n\n미드우퍼에는 후면 패널에 통풍구가 추가되어 저주파 과도 현상을 개선하고 보이스 코일 열 방출을 향상시킵니다. 포괄적이고 세부적인 하드웨어 조정을 통해 자연스럽고 편안한 음역을 제공합니다."}]'::jsonb, '[{"id":1770341280813,"name":"DP-653_OM_English","url":"assets/files/DP-653_OM_English.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770342281262, 'Speakers', 'DP2-653NW', 'DP2-653 네트워크', '.', 290000, 'assets/images/spk-dp2nw.jpg', '[{"id":1770342115123.8748,"type":"text","value":"FEATURES\nTweeter : 6kHz – 24kHz / 4-8$\\Omega$ / 6dB/Oct\nMidrange : 1.4kHzkHz – 6kHz / 4-8$\\Omega$ / 6dB/Oct\nWoofer : 20Hz – 1.4kHz / 4-8$\\Omega$ / 6dB/Oct"},{"id":1770342199764.687,"type":"image","value":"assets/images/spk-dp2nw-01.jpg"},{"id":1770342230926.095,"type":"text","value":"Hi-Res 대응 및 유닛 사운드 특성 조정과 함께 크로스오버 하드웨어 설계를 재보정하여 다중 주파스 네트워크에 탁월하고 균형잡힌 음질을 제공합니다."}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
