INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770342988896, 'Speakers', 'DP2-35M', '3.5" Midrange Speaker Set', '장착 공임 별도/20만원 부터', 280000, 'assets/images/spk-DP235M.jpg', '[{"id":1770342935416.1565,"type":"text","value":"90Hz~12kHz\nPeak 240W\nSensitivity : 81dB"},{"id":1770342999794.1309,"type":"image","value":"assets/images/spk-dp2653-01.jpg"},{"id":1770343036338.5276,"type":"text","value":"DP2 스피커는 60Hz부터 40,000Hz의 주파스를 재생할 수 있어 음악을 원래 음원에 더 가깝게 만듭니다."},{"id":1770343043598.6377,"type":"image","value":"assets/images/spk-dp2653-02.jpg"},{"id":1770343054376.167,"type":"text","value":"예술 작품에 가깝습니다.\n\n외관 디자인은 고품질 알루미늄 합금 소재를 사용하여\n재생 공명을 효과적으로 제거하고 정확한 사운드 성능을 보장합니다."},{"id":1770343067674.2983,"type":"image","value":"assets/images/spk-dp2653-03.jpg"},{"id":1770343076054.4976,"type":"text","value":"세계 최초 \"Hybrid fiber\"를 사용하였습니다.\n\n고강성 탄소섬유는 베이스의 힘을 반영하고, 고강성 방탄섬유는 미드톤의 부드러운 목소리를 선명하게 반영하며, 통일된 진동판 소재를 사용한 베이스 유닛인 미드톤은 넓은 범위의 음원을 자연스럽게 합니다.\n\nHAMR Surround 채용\n\n알파인의 고유 기술인 H.A.M.R(High Amplitude Multi-Roll) 서라운드는 고급 사운드 시스템을 채택하여 높은 출력과 뛰어난 음질을 구현합니다."}]'::jsonb, '[{"id":1770342932474,"name":"DP-653_OM_English","url":"assets/files/DP-653_OM_English.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770343496220, 'Speakers', 'S2-S65C', '6.5" Component Speaker Set', '장착 공임 별도/20만원 부터', 270000, 'assets/images/spk-s65c.jpg', '[{"id":1770343366648.9526,"type":"text","value":"Hi-Res Audio Certified: (Up to 40kHz)\nCone Material: Poly Propylene, Glass Fiber, and Mica Cone Material\nDesign: Lightweight Design with High Output and Low Distortion\nSurround: High-Amplitude Multi-Roll (H.A.M.R.) Surround\nTweeters: Included 1” Adjustable Tweeters with Threaded Removable Housing (Component)\nCrossovers: OEM Fitment with In-Line Crossovers\nCompatibility: Compatible with KTE-S65G Speaker Grille (sold separately)\n\nTECH SPECS\nWoofer Size: 6.5”\nTweeter Size: 1” (Component)\nPower Handling: 240W Peak\nFrequency Response: 70Hz - 40kHz (Hi-Res)\nSensitivity: 88dB"},{"id":1770343417594.922,"type":"image","value":"assets/images/Hi-res.jpg"},{"id":1770343462044.4707,"type":"text","value":"하이레졸루션 오디오(Hi-Res Audio)란 무엇인가?\n\n하이레졸루션 오디오 스트리밍 서비스와 음악 다운로드가 보편화되면서, 이제 CD보다 높은 샘플링 레이트로 음악을 재생하여 좋아하는 트랙에 생동감과 극강의 선명함을 더할 수 있게 되었습니다. Alpine의 하이레졸루션 오디오 인증 헤드 유닛, 앰프 및 디지털 신호 프로세서(DSP)는 최대 192kHz/24Bit의 고해상도 소스 및 녹음물로부터 원음에 충실한 오디오 재생을 구현하도록 정밀하게 설계되었습니다. 이러한 구성 요소들은 아티스트의 원본 녹음에 가까운 고화질 재생과 압도적인 성능을 위해 최적화되어 있습니다.\n\n왜 하이레졸루션 오디오인가?\n\n고해상도 오디오를 감상하면 음악 속의 모든 감정을 느끼고 미세한 뉘앙스까지 포착할 수 있습니다. 좋아하는 아티스트가 스튜디오에서 선보인 오리지널 퍼포먼스의 모든 디테일이 완벽하게 재현되기 때문입니다. 하이레졸루션 오디오는 왜곡이 전혀 없는 궁극의 청취 경험을 제공합니다.\n\n왜 하이레졸루션 오디오 인증 스피커인가?\n\n하이레졸루션 오디오는 일반 스피커의 한계를 뛰어넘습니다. 고해상도 음원과 녹음물을 진정한 고화질로 정확하게 표현하기 위해서는 최대 40kHz에 이르는 확장된 다이내믹 주파수 범위를 재생하는 능력이 무엇보다 중요합니다."},{"id":1770343534339.8833,"type":"image","value":"assets/images/spk-s65c-01.jpg"},{"id":1770343545645.033,"type":"text","value":"하이레졸루션 오디오(Hi-Res Audio) 인증\n\nS-시리즈를 위해 완전히 새로워진 하이레졸루션 오디오 인증은 여러분의 일상적인 드라이브에 완전히 새로운 차원의 탁월한 음향을 선사합니다. 최대 40kHz에 이르는 고차 배음(upper harmonics)을 재생하는 인상적인 확장 다이내믹 레인지를 통해, 모든 곡은 원본 녹음에 충실한 수준의 디테일과 미세한 뉘앙스가 더해져 생동감 있게 살아납니다."},{"id":1770343598725.5823,"type":"image","value":"assets/images/spk-s65c-02.jpg"},{"id":1770343605209.9014,"type":"text","value":"HAMR 서라운드 (High-Amplitude Multi-Roll)\n\nAlpine의 특허받은 HAMR(고진폭 멀티롤) 서라운드는 높은 음압(SPL)을 내기 위해 콘이 격렬하게 움직이는 모든 단계에서도 진동판을 완벽하게 제어합니다. 또한, 일반적인 돔 형태 서라운드의 최대 선형 진폭을 훨씬 뛰어넘는 성능을 통해, 왜곡 없이 아름답고 순수한 사운드와 가슴을 울리는 강력한 저음을 선사합니다."},{"id":1770343680799.4954,"type":"image","value":"assets/images/spk-s65c-03.jpg"},{"id":1770343707795.6182,"type":"text","value":"유리 섬유 복합소재 우퍼 콘 (Glass Fiber Composite Woofer Cone)\n\n도어 우퍼에는 완전히 새로워진 유리 섬유 복합소재 콘이 적용되었습니다. 이 콘은 방향성을 고려한 **직조 구조(Directionally weaved construction)**로 설계되어, 기존의 일반적인 타원형 콘 진동판보다 훨씬 더 강력한 내구성을 자랑합니다. 이러한 뛰어난 강성과 유리 섬유 고유의 가벼움이 결합되어 콘의 진폭(Excursion)을 정밀하게 제어하며, 그 결과 탁월한 응답성과 고품질의 오디오 재현력을 선사합니다."},{"id":1770343753757.4905,"type":"image","value":"assets/images/spk-s65c-04.jpg"},{"id":1770343763169.4993,"type":"text","value":"다용도 트위터 설치 (Versatile Tweeter Installation)\n\n1인치 소프트 돔 트위터는 다양한 설치 방법에 대응할 수 있도록 설계되었습니다.\n\n정밀한 지향각 조절: 매립형(Flush mount)으로 장착이 가능하며, 하우징 내에서 스위블(Swivel) 기능을 통해 소리의 초점이 맺히는 정확한 ''스위트 스팟(Sweet spot)''을 찾아 각도를 조절할 수 있습니다.\n\n스텔스(Stealth) 인스톨: 외관상 드러나지 않는 깔끔한 장착을 위해 프레임을 제거할 수 있습니다. 이 경우 크기가 원래의 아주 일부분 수준으로 줄어들어 어떤 설치 환경에도 유연하게 대응합니다."},{"id":1770343851711.7217,"type":"image","value":"assets/images/spk-s65c-05.jpg"},{"id":1770343860315.8782,"type":"text","value":"대형 마그넷 구조 (Large Magnet Structure)\n\nS-시리즈 스피커 후면에 탑재된 대형 스트론튬 마그넷은 압도적인 성능을 자랑합니다.\n\n이 마그넷은 대형 보이스 코일 및 Alpine의 특허받은 HAMR 서라운드와 결합하여, 콘의 진폭(Excursion)과 드라이버의 구동력을 높여줍니다.\n\n그 결과, 더욱 크고 타격감 넘치는(Punchy) 사운드를 선사합니다."}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
