INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770345538900, 'Speakers', 'S2-S10TW', '1" Tweeter Set', '장착 공임 별도/20만원 부터', 150000, 'assets/images/spk-S2tw.jpg', '[{"id":1770345443360.149,"type":"text","value":"FEATURES\nTwo (2) 1” Tweeters\nHigh-Grade Neodymium Motor Structure\nSilk Dome Tweeter Design\nRemoveable Alpine Logo\nIncludes a 15-degree Swivel Flush Cup Housing\nIncludes a height adjustable stealth OEM mount\nCompatible with Alpine’s S-Series\n\nTECH SPECS\nPeak Power Capacity: 240W\nMaterial: Silk\nMagnet Type: Neodymium\nVoice Coil Type: Copper Clad Aluminum\nCrossover: Passive 12dB/Octave High-Pass Filter\nFrequency Response: 1kHz-22kHz\nSensitivity: 88dB (1W / 1m)\nImpedance: 6 Ohm\nFlush Mounting Depth: 17.6mm\nCutout Diameter: 51mm"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770345793630, 'Speakers', 'DM-65C', '6.5" Component Speaker Set', '장착 공임 별도/20만원 부터', 200000, 'assets/images/spk-dm65c.jpg', '[{"id":1770345714274.7483,"type":"text","value":"FEATURES\nSpeaker type\n6-1/2\" (16.5 cm) Component 2-Way Speakers\n\nFrequency response\n65 Hz - 20 kHz\n\nPower handling\n180 Watts peak power\n\nSensitivity\n90 dB\n\nDesign\nShallow Mounting Design\n\nMateriaㅣ\nSoft dome tweeter\nNeodymium Magnet for tweeter\nFerrite Magnet for woofer\nPolypropylene Cone"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770345922698, 'Speakers', 'DM-65', '6.5" Coaxial Speaker Set', '장착 공임 별도/20만원 부터', 150000, 'assets/images/spk-dm65.jpg', '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770346228726, 'Speakers', 'RS-W10D2', '10" Subwoofer Shallow with Dual 2 Ohm', '장착 공임 별도/20만원 부터', 1500000, 'assets/images/spk-RSw10.jpg', '[{"id":1770346208126.7747,"type":"text","value":"High-Performance Shallow Bass Driver\nAlpine Gen2 DD Linear Magnetic Circuit\nCast Aluminum Frame\nAluminum Dust Cap\nNeodymium Magnet\nMounting Depth: 3.25”\nX-Max: 20mm\nVoice Coil: 4” (102mm)\nFrequency Response: 25Hz-100Hz\nSensitivity: 79 dB\nNominal Impedance: 2 Ohm for RS-W10D4\nPower Handling: 600W RMS / 1800W Peak\nCompatible with KTE-RS10G Subwoofer Grille Kit (Sold Separately)"},{"id":1770346301427.0574,"type":"text","value":"완전히 새로운 R-시리즈 슬림형(Shallow Profile) 서브우퍼\n완전히 새로운 R-시리즈 슬림형 서브우퍼는 모든 면에서 극한을 추구하며, 강인하고 거친 외관에 걸맞은 강력한 베이스 출력을 자랑합니다.\n\n주요 특징 및 성능\n혁신적인 슬림 디자인: Alpine은 최첨단 디자인과 엔지니어링 혁신을 결합하여, 베이스 출력과 품질을 전혀 타협하지 않으면서도 초슬림 프로필을 완성해 컴팩트 베이스의 수준을 한 단계 높였습니다.\n\n강력한 구동 시스템: 강력한 네오디뮴 마그넷과 결합된 독점적인 듀얼 갭 모터 구조를 통해 600W RMS 및 1800W 최대 출력의 높은 전력 처리가 가능합니다.\n\n정밀한 베이스 재현: 맞춤형 캐스트 알루미늄 프레임과 획기적인 우퍼 콘 디자인은 20mm의 경이로운 선형 X-max를 실현하여 최상의 베이스 성능을 보장합니다.\n\n완벽한 조화: Alpine의 R-시리즈 슬림형 서브우퍼는 크기와 사운드라는 두 마리 토끼를 모두 잡은 제품입니다.\n\n디자인과 보호의 완성\n프리미엄 옵션: 선택 사항인 메쉬 그릴(KTE-RS10G)은 커스텀 설치 시 강인한 인상과 프리미엄 마감을 더해주며, 장비를 안전하게 보호하는 역할까지 수행합니다."},{"id":1770346338225.261,"type":"image","value":"assets/images/spk-RSw10-01.jpg"},{"id":1770346348101.4968,"type":"text","value":"초슬림 디자인 (Ultra-Shallow Design)\n\n차량에 강력하고 깊은 타격감의 베이스를 추가하고 싶지만, 서브우퍼를 설치할 공간이 부족해 고민하셨던 분들을 위한 최적의 솔루션입니다. Alpine의 R-시리즈 슬림형 서브우퍼는 기존 R-시리즈 라인업에서 기대해 온 압도적인 성능과 강력한 사운드를 그대로 구현합니다. 이제 대부분의 차량 환경에 완벽하게 어우러지도록 설계된 슬림한 프로필로 R-시리즈의 명성을 그대로 경험해 보세요."},{"id":1770346470957.2363,"type":"image","value":"assets/images/spk-RSw10-02.jpg"},{"id":1770346481103.0986,"type":"text","value":"극한의 출력 (Extreme Output)\n\n크기에 속지 마세요: R-시리즈 슬림형 서브우퍼는 슬림한 설계임에도 불구하고, 풀사이즈 R2-시리즈 서브우퍼와 동일한 **20mm 콘 진폭(Excursion)**을 자랑하며 압도적인 출력을 구현합니다.\n\n강력한 핵심 기술: 제품의 중심에는 강력한 네오디뮴 마그넷으로 제어되는 4인치(102mm) 대형 보이스 코일이 탑재되어 있습니다.\n\n탁월한 전력 처리: 이를 통해 600W RMS의 안정적인 정격 출력을 처리하며 깊고 타격감 넘치는 베이스를 선사합니다."},{"id":1770346526267.326,"type":"image","value":"assets/images/spk-RSw10-03.jpg"},{"id":1770346536799.7717,"type":"text","value":"강력한 베이스 투사 (Powerful Bass Projection)\n\n가볍지만 단단한 알루미늄 소재를 활용하여 슬림한 크기에도 불구하고 압도적인 저음 전달력을 갖췄습니다.\n\n알루미늄 더스트 캡: 가벼우면서도 강성이 뛰어난 알루미늄 더스트 캡을 채택하여 왜곡을 최소화하고 소리를 신속하게 전환합니다.\n\n베이스 투사: 스피커 표면에서 베이스를 힘있게 밀어내어(Project), 타격감 넘치면서도 부드러운 저음 성능을 구현합니다."},{"id":1770346578947.2942,"type":"image","value":"assets/images/spk-RSw10-04.jpg"},{"id":1770346593947.3179,"type":"text","value":"정밀한 베이스 제어 (Precise Bass Control)\n\nAlpine의 2세대 DD-리니어 자기 회로(Gen2 DD-Linear Magnetic Circuit) 기술은 콤팩트하고 효율적인 듀얼 갭(Dual-gap) 보이스 코일 구조를 채택하여 모터를 더욱 우수하고 선형적으로 제어할 수 있게 해줍니다. 그 결과, 소리의 왜곡을 줄이고 정밀한 베이스 제어를 실현합니다."},{"id":1770346638007.7415,"type":"image","value":"assets/images/spk-RSw10-05.jpg"},{"id":1770346649115.122,"type":"text","value":"프리미엄 설계 (Premium Construction)\n\nR-시리즈 슬림형 서브우퍼는 다이캐스트 알루미늄 프레임을 사용하여 견고하고 단단하게 제작되었습니다.\n\n이러한 구조는 높은 에너지 전달력을 보장하며, 프레임 자체에서 발생할 수 있는 공진(Resonance)을 효과적으로 억제합니다."}]'::jsonb, '[{"id":1770346263757,"name":"R-Series_Shallow_Subwoofers_OM","url":"assets/files/R-Series_Shallow_Subwoofers_OM.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;